import { useRef, useState, useEffect } from 'preact/hooks';
import { FunctionComponent } from 'preact';

import styles from './styles.module.scss';

interface Props {
  message: any
}

const GifPreview: FunctionComponent<Props> = ({ message }: Props) => {
  const [loops, setLoops] = useState(1);
  const [isLoaded, setLoaded] = useState(false);
  const videoRef = useRef<HTMLVideoElement>();

  useEffect(() => {
    setLoaded(false);
  }, [message.imgSrc]);

  const handleVideoLoop = (el) => {
    if (message.loops) {
      setLoops((v) => ++v);

      if (loops !== message.loops) el.play();
      return;
    }

    el.play();
  };

  const handleVideoLoaded = () => {
    setLoaded(true);
  };

  const getDimensions = () => {
    if (!videoRef.current || !isLoaded) return {};
    const { width, height } = videoRef.current.getBoundingClientRect();
    return width && height ? { width, height, display: 'block' } : {};
  };

  const dimensions = getDimensions();
  // console.log('dimensions', dimensions);
  // style={dimensions}

  return (
    <div className={styles.friendsGifPreviewContainer}>
      <video
        ref={videoRef}
        className={styles.image}
        src={message.imgSrc}
        onEnded={(e) => handleVideoLoop(e.target)}
        muted
        autoPlay
        onPlay={handleVideoLoaded}
        onLoad={handleVideoLoaded}
      />
      {message.message && isLoaded && (
        <div className={styles.gifText}>{message.message}</div>
      )}
    </div>
  );
};

export default GifPreview;
